// recipe: body-motion
// args: none
// returns: ok, moveX, moveY, posX, posY, velX, velY, instanceId, bodyName, modal, spectator
//
// Reads what the local player's body is actually doing: the movement vector the game set from its own binds
// (`PlayerCamera.cs:1066-1067` writes `body.moveDir` from `Input.GetKey(...)`) and the body's velocity and position.
// A row that stages a movement key and sees the body stay put can tell whether the game never read the key or the body
// is being held back (measured 2026-11-22: twenty-four 400 ms steps moved the body one unit).
//
// `instanceId` and `bodyName` are here because two samples of the same walk read x = +4.085 and x = -4.085, and a
// position that mirrors between samples means the row is not reading the same body twice.
//
// `modal` and `spectator` are the two reasons the game's own input patch refuses a frame
// (`PlayerCameraHandleInputPatch.cs:36-45`): while the CUO window reads as modal, or while a spectator owns the
// input, `HandleInput` never runs and `moveDir` stays zero no matter what key is staged.
//
// ONE LINE ON PURPOSE: the client's evaluator takes one top-level expression.
((System.Func<string>)(() => { var body = PlayerCamera.main == null ? null : PlayerCamera.main.body; if (body == null) { return "{\"ok\":false,\"error\":\"no-local-body\"}"; } var dir = body.moveDir; var rbGet = new System.Func<string, string>((what) => { try { var field = body.GetType().GetField("rb", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic); var rb = field == null ? null : field.GetValue(body); if (rb == null) { return "none"; } var property = rb.GetType().GetProperty(what); if (property != null) { return System.Convert.ToString(property.GetValue(rb, null), System.Globalization.CultureInfo.InvariantCulture); } var rbField = rb.GetType().GetField(what, System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic); return rbField == null ? "none" : System.Convert.ToString(rbField.GetValue(rb), System.Globalization.CultureInfo.InvariantCulture); } catch { return "error"; } }); var unit = body.GetComponent<Rigidbody2D>(); var at = body.transform.position; var vx = unit == null ? 0f : unit.velocity.x; var vy = unit == null ? 0f : unit.velocity.y; var name = body.gameObject == null ? "" : body.gameObject.name.Replace("\"", "''"); var modal = "none"; var spectator = "none"; var assemblies = System.AppDomain.CurrentDomain.GetAssemblies(); var bridgeType = (System.Type)null; for (var i = 0; i < assemblies.Length && bridgeType == null; i++) { System.Type[] types; try { types = assemblies[i].GetTypes(); } catch { continue; } for (var t = 0; t < types.Length; t++) { if (types[t].Name == "PatchBridge") { bridgeType = types[t]; break; } } } if (bridgeType != null) { const System.Reflection.BindingFlags Flags = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; var surfaceProperty = bridgeType.GetProperty("SessionSurface", Flags); var surface = surfaceProperty == null ? null : surfaceProperty.GetValue(null, null); if (surface != null) { var modalProperty = surface.GetType().GetProperty("IsOnlineUiModalOpen"); if (modalProperty != null) { modal = ((bool)modalProperty.GetValue(surface, null)) ? "true" : "false"; } } } var spectatorType = (System.Type)null; for (var i = 0; i < assemblies.Length && spectatorType == null; i++) { System.Type[] types; try { types = assemblies[i].GetTypes(); } catch { continue; } for (var t = 0; t < types.Length; t++) { if (types[t].Name == "SpectatorPresentationGate") { spectatorType = types[t]; break; } } } if (spectatorType != null) { var active = spectatorType.GetProperty("IsActive", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic); if (active != null) { spectator = ((bool)active.GetValue(null, null)) ? "true" : "false"; } } return "{\"ok\":true,\"moveX\":" + dir.x + ",\"moveY\":" + dir.y + ",\"posX\":" + at.x + ",\"posY\":" + at.y + ",\"velX\":" + vx + ",\"velY\":" + vy + ",\"instanceId\":" + body.GetInstanceID() + ",\"bodyName\":\"" + name + "\",\"modal\":\"" + modal + "\",\"spectator\":\"" + spectator + "\",\"speed\":" + body.actualMaxSpeed + ",\"legs\":\"" + (body.hasLegs ? "true" : "false") + "\",\"legMult\":" + body.legSpeedMult + ",\"grounded\":\"" + (body.grounded ? "true" : "false") + "\",\"moving\":\"none\",\"forceWalk\":\"" + (body.forceWalk ? "true" : "false") + "\",\"standing\":\"" + (body.standing ? "true" : "false") + "\",\"rbSim\":\"" + rbGet("simulated") + "\",\"rbType\":\"" + rbGet("bodyType") + "\",\"rbFreeze\":\"" + rbGet("constraints") + "\",\"rbPos\":\"" + rbGet("position") + "\",\"rbVel\":\"" + rbGet("velocity") + "\"}"; }))()

